import React from 'react';
import { DataTable, Pagination } from 'carbon-components-react';

const rows = Array.from({ length: 650 }, (_, index) => ({
  id: index.toString(),
  name: `Item ${index + 1}`,
  status: 'Active',
}));

const headers = [
  { key: 'name', header: 'Name' },
  { key: 'status', header: 'Status' },
];

function App() {
  return (
    <DataTable
      rows={rows}
      headers={headers}
      render={({ rows, headers, getHeaderProps, getRowProps }) => (
        <div>
          <table>
            <thead>
              <tr>
                {headers.map(header => (
                  <th {...getHeaderProps({ header })}>{header.header}</th>
                ))}
              </tr>
            </thead>
            <tbody>
              {rows.map(row => (
                <tr {...getRowProps({ row })}>
                  {row.cells.map(cell => (
                    <td key={cell.id}>{cell.value}</td>
                  ))}
                </tr>
              ))}
            </tbody>
          </table>
          <Pagination
            totalItems={650}
            pageSize={10}
            pageSizes={[10, 20, 30, 40, 50]}
          />
        </div>
      )}
    />
  );
}

export default App;
